#include <iostream>

class Counter {
    // Good Practice: friendship declarations placed first
    friend void setCounter(Counter& c, int value);
    friend void showCounter(const Counter& c);

public:
    Counter() : count(0) {}

private:
    int count;
};

// Standalone friend functions
void setCounter(Counter& c, int value) {
    c.count = value; // Direct access to private member count
}

void showCounter(const Counter& c) {
    std::cout << "count: " << c.count << "\n";
}

int main() {
    Counter c;
    showCounter(c);
    setCounter(c, 42);
    showCounter(c);
    return 0;
}

#include <iostream>

class Time {
public:
    explicit Time(int hour = 0) {
        setHour(hour);
    }

    void setHour(int hour) {
        // Parameter 'hour' hides data member 'hour'
        // Use this->hour to explicitly target the member variable
        if (hour >= 0 && hour < 24) {
            this->hour = hour;
        } else {
            this->hour = 0;
        }
    }

    int getHour() const {
        return this->hour; // explicit use, same as returning hour
    }

private:
    int hour;
};

int main() {
    Time t;
    t.setHour(18);
    std::cout << "Hour: " << t.getHour() << "\n";
    std::cout << "Size of Time: " << sizeof(t) << " bytes\n";
    return 0;
}
